import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import DashboardLayout from '../components/DashboardLayout';
import { useAuth } from '../App';

const mockData = {
  weather: { temp: 28, humidity: 65, rainfall: 12, wind: 14, condition: 'Partly Cloudy', icon: '⛅' },
  soil: { type: 'Black Cotton', ph: 6.8, nitrogen: 'Medium', moisture: 58 },
  crop: { name: 'Wheat', confidence: 94, season: 'Rabi', duration: '120 days' },
  profit: { estimated: 42000, perAcre: 8400, marketPrice: 2150, trend: '+12%' },
  risk: { level: 'Low', score: 18, diseases: ['Rust', 'Blight'], alert: 'Monitor moisture levels' },
};

function MetricCard({ icon, label, value, sub, color = 'green', onClick }) {
  const colors = { green: 'from-green-900/40 to-green-950/40 border-green-800/30', blue: 'from-blue-900/40 to-blue-950/40 border-blue-800/30', yellow: 'from-yellow-900/40 to-yellow-950/40 border-yellow-800/30', red: 'from-red-900/40 to-red-950/40 border-red-800/30', purple: 'from-purple-900/40 to-purple-950/40 border-purple-800/30' };
  const textColors = { green: 'text-green-400', blue: 'text-blue-400', yellow: 'text-yellow-400', red: 'text-red-400', purple: 'text-purple-400' };
  return (
    <div onClick={onClick} className={`bg-gradient-to-br ${colors[color]} border rounded-2xl p-5 card-hover ${onClick ? 'cursor-pointer' : ''} backdrop-blur-sm`}>
      <div className="flex items-start justify-between mb-3">
        <span className="text-2xl">{icon}</span>
        {sub && <span className={`text-xs font-medium ${textColors[color]} glass-green px-2 py-0.5 rounded-full`}>{sub}</span>}
      </div>
      <div className={`font-display font-bold text-2xl ${textColors[color]} mb-1`}>{value}</div>
      <div className="text-gray-400 text-sm">{label}</div>
    </div>
  );
}

function RiskBadge({ level }) {
  const map = { Low: 'bg-green-500/20 text-green-400 border-green-500/30', Medium: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', High: 'bg-red-500/20 text-red-400 border-red-500/30' };
  return <span className={`px-3 py-1 rounded-full text-xs font-bold border ${map[level]}`}>{level} Risk</span>;
}

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [time, setTime] = useState(new Date());
  const d = mockData;

  useEffect(() => { const t = setInterval(() => setTime(new Date()), 60000); return () => clearInterval(t); }, []);

  const hour = time.getHours();
  const greeting = hour < 12 ? 'Good Morning' : hour < 17 ? 'Good Afternoon' : 'Good Evening';

  const quickActions = [
    { icon: '🔬', label: 'Scan Disease', path: '/disease-scanner', color: 'from-red-900/30 to-red-950/30 border-red-800/30' },
    { icon: '🌱', label: 'Get Crop Tips', path: '/recommendations', color: 'from-green-900/30 to-green-950/30 border-green-800/30' },
    { icon: '🌦️', label: 'Weather Forecast', path: '/weather', color: 'from-blue-900/30 to-blue-950/30 border-blue-800/30' },
    { icon: '🤖', label: 'Ask KisanGPT', path: '/chatbot', color: 'from-purple-900/30 to-purple-950/30 border-purple-800/30' },
  ];

  return (
    <DashboardLayout title="Farm Dashboard" subtitle={`${time.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' })}`}>
      {/* Greeting */}
      <div className="glass rounded-2xl p-6 mb-6 border border-green-900/30 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="font-display font-bold text-2xl text-white">{greeting}, {user?.name || 'Farmer'} 👋</h2>
          <p className="text-gray-400 text-sm mt-1">Your farm is looking healthy today. AI has 3 new recommendations for you.</p>
        </div>
        <div className="flex items-center gap-3">
          {user?.gps && <div className="glass-green px-3 py-2 rounded-xl text-green-300 text-xs">📍 {user.gps.lat}, {user.gps.lng}</div>}
          <div className="glass px-3 py-2 rounded-xl text-gray-300 text-xs">{user?.acres || '5'} Acres · {user?.crop || 'Wheat'}</div>
        </div>
      </div>

      {/* Main Metrics */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <MetricCard icon="🌡️" label="Temperature" value={`${d.weather.temp}°C`} sub={d.weather.condition} color="yellow" onClick={() => navigate('/weather')} />
        <MetricCard icon="💧" label="Humidity" value={`${d.weather.humidity}%`} sub="Optimal" color="blue" onClick={() => navigate('/weather')} />
        <MetricCard icon="🌧️" label="Rainfall" value={`${d.weather.rainfall}mm`} sub="This Week" color="blue" onClick={() => navigate('/weather')} />
        <MetricCard icon="💨" label="Wind Speed" value={`${d.weather.wind} km/h`} sub="Light Breeze" color="green" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
        {/* Soil Card */}
        <div className="glass rounded-2xl p-6 border border-green-900/30">
          <div className="flex items-center gap-2 mb-4">
            <span className="text-xl">🪨</span>
            <h3 className="font-display font-semibold text-white">Soil Analysis</h3>
          </div>
          <div className="space-y-3">
            {[
              { label: 'Soil Type', value: d.soil.type, color: 'text-amber-400' },
              { label: 'pH Level', value: d.soil.ph, color: 'text-green-400' },
              { label: 'Nitrogen', value: d.soil.nitrogen, color: 'text-blue-400' },
              { label: 'Moisture', value: `${d.soil.moisture}%`, color: 'text-cyan-400' },
            ].map(item => (
              <div key={item.label} className="flex justify-between items-center">
                <span className="text-gray-400 text-sm">{item.label}</span>
                <span className={`font-semibold text-sm ${item.color}`}>{item.value}</span>
              </div>
            ))}
            <div className="mt-2">
              <div className="flex justify-between text-xs text-gray-500 mb-1"><span>Moisture Level</span><span>{d.soil.moisture}%</span></div>
              <div className="h-2 bg-black/40 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-green-600 to-green-400 rounded-full transition-all" style={{ width: `${d.soil.moisture}%` }} />
              </div>
            </div>
          </div>
        </div>

        {/* Crop Recommendation */}
        <div className="glass rounded-2xl p-6 border border-green-900/30 cursor-pointer card-hover" onClick={() => navigate('/recommendations')}>
          <div className="flex items-center gap-2 mb-4">
            <span className="text-xl">🌱</span>
            <h3 className="font-display font-semibold text-white">AI Crop Recommendation</h3>
          </div>
          <div className="text-center py-4">
            <div className="text-6xl mb-3">🌾</div>
            <div className="font-display font-bold text-3xl gradient-text mb-1">{d.crop.name}</div>
            <div className="text-gray-400 text-sm mb-4">{d.crop.season} Season · {d.crop.duration}</div>
            <div className="glass-green rounded-xl p-3">
              <div className="text-green-300 text-xs mb-1">AI Confidence</div>
              <div className="h-2 bg-black/40 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-green-600 to-green-400 rounded-full" style={{ width: `${d.crop.confidence}%` }} />
              </div>
              <div className="text-green-400 font-bold text-sm mt-1">{d.crop.confidence}%</div>
            </div>
          </div>
          <div className="text-center text-green-400 text-xs">Tap for full recommendations →</div>
        </div>

        {/* Profit & Risk */}
        <div className="space-y-4">
          <div className="glass rounded-2xl p-5 border border-green-900/30 cursor-pointer card-hover" onClick={() => navigate('/recommendations')}>
            <div className="flex items-center gap-2 mb-3">
              <span className="text-lg">💰</span>
              <h3 className="font-semibold text-white text-sm">Profit Prediction</h3>
            </div>
            <div className="font-display font-black text-3xl gradient-text-gold">₹{d.profit.estimated.toLocaleString()}</div>
            <div className="text-gray-400 text-xs mt-1">Estimated this season</div>
            <div className="flex items-center gap-2 mt-3">
              <span className="text-green-400 text-xs font-semibold">{d.profit.trend} vs last year</span>
              <span className="text-gray-500 text-xs">· ₹{d.profit.perAcre}/acre</span>
            </div>
          </div>

          <div className="glass rounded-2xl p-5 border border-green-900/30 cursor-pointer card-hover" onClick={() => navigate('/disease-scanner')}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <span className="text-lg">⚠️</span>
                <h3 className="font-semibold text-white text-sm">Disease Risk</h3>
              </div>
              <RiskBadge level={d.risk.level} />
            </div>
            <div className="text-gray-400 text-xs mb-2">{d.risk.alert}</div>
            <div className="flex gap-2 flex-wrap">
              {d.risk.diseases.map(dis => (
                <span key={dis} className="text-xs bg-red-900/20 text-red-400 border border-red-800/30 px-2 py-0.5 rounded-full">{dis}</span>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div>
        <h3 className="font-display font-semibold text-white mb-4">Quick Actions</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {quickActions.map(a => (
            <button key={a.path} onClick={() => navigate(a.path)}
              className={`bg-gradient-to-br ${a.color} border rounded-2xl p-5 text-center card-hover backdrop-blur-sm`}>
              <div className="text-3xl mb-2">{a.icon}</div>
              <div className="text-white text-sm font-medium">{a.label}</div>
            </button>
          ))}
        </div>
      </div>
    </DashboardLayout>
  );
}
